"use strict";(self.webpackChunktil=self.webpackChunktil||[]).push([["3529"],{57983(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>d,frontMatter:()=>s,contentTitle:()=>r,toc:()=>h,assets:()=>l});var a=JSON.parse('{"id":"ai-why-companies-struggle-agentic-ai-en","title":"Why Companies Can\'t Get Agentic AI Off the Ground: It\'s Not a Technology Problem \u2014 It\'s Four Organizational Walls","description":"Over the past year, I\'ve put agentic AI into a real development workflow, and I gave a talk on the topic at COSCUP. Seen from the tech community, agentic AI looks like the next productivity revolution. Seen from inside a company, most rollouts stall \u2014 and where they stall almost never has anything to do with the technology.","source":"@site/docs/ai-why-companies-struggle-agentic-ai-en.md","sourceDirName":".","slug":"/ai-why-companies-struggle-agentic-ai-en","permalink":"/til/docs/ai-why-companies-struggle-agentic-ai-en","draft":false,"unlisted":false,"editUrl":"https://github.com/alanhc/til/tree/main/docs/ai-why-companies-struggle-agentic-ai-en.md","tags":[],"version":"current","frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"AI \u8F14\u52A9\u97CC\u9AD4\u958B\u767C\uFF1AMCP\u3001Skills \u8207 Harness \u7684\u4E09\u5C64\u62C6\u89E3","permalink":"/til/docs/ai-firmware-mcp-skills-harness"},"next":{"title":"\u70BA\u4EC0\u9EBC\u516C\u53F8\u63A8\u4E0D\u52D5 Agentic AI:\u4E0D\u662F\u6280\u8853\u554F\u984C,\u662F\u56DB\u9053\u7D44\u7E54\u7684\u7246","permalink":"/til/docs/ai-why-companies-struggle-agentic-ai"}}'),i=n(74848),o=n(28453);let s={},r="Why Companies Can't Get Agentic AI Off the Ground: It's Not a Technology Problem \u2014 It's Four Organizational Walls",l={},h=[{value:"Wall #1: Management Feels It &quot;Can&#39;t Be Controlled&quot;",id:"wall-1-management-feels-it-cant-be-controlled",level:2},{value:"Wall #2: When Something Breaks, No One Knows Who&#39;s Responsible",id:"wall-2-when-something-breaks-no-one-knows-whos-responsible",level:2},{value:"Wall #3: Colleagues Fear Being Replaced",id:"wall-3-colleagues-fear-being-replaced",level:2},{value:"Wall #4: When the Agent Dismantles Your Role, Who&#39;s Approving That PR?",id:"wall-4-when-the-agent-dismantles-your-role-whos-approving-that-pr",level:2},{value:"An Old Fault Line, Amplified by Agents: Security vs. RD",id:"an-old-fault-line-amplified-by-agents-security-vs-rd",level:2},{value:"So What Do You Do? \u2014 Four Handholds, Not Answers",id:"so-what-do-you-do--four-handholds-not-answers",level:2},{value:"Back to First Principles: None of These Walls Were Built by the Agent",id:"back-to-first-principles-none-of-these-walls-were-built-by-the-agent",level:2},{value:"References",id:"references",level:2}];function c(e){let t={a:"a",blockquote:"blockquote",em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",ol:"ol",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"why-companies-cant-get-agentic-ai-off-the-ground-its-not-a-technology-problem--its-four-organizational-walls",children:"Why Companies Can't Get Agentic AI Off the Ground: It's Not a Technology Problem \u2014 It's Four Organizational Walls"})}),"\n",(0,i.jsx)(t.p,{children:"Over the past year, I've put agentic AI into a real development workflow, and I gave a talk on the topic at COSCUP. Seen from the tech community, agentic AI looks like the next productivity revolution. Seen from inside a company, most rollouts stall \u2014 and where they stall almost never has anything to do with the technology."}),"\n",(0,i.jsx)(t.p,{children:"What actually kills a proposal to \"let an AI agent take over the development of some module\" is a handful of very human things: management feels it can't be controlled, no one knows who's responsible when something breaks, and colleagues fear being replaced. And even once it does ship, there's one more wall that fewer people talk about but that sits closest to the engineering floor \u2014 an agent dismantles a person's role and quietly relocates responsibility to code review, a place no one prepared for. I've watched all of this happen firsthand, and as it turns out, academia has already written it all up."}),"\n",(0,i.jsx)(t.h2,{id:"wall-1-management-feels-it-cant-be-controlled",children:'Wall #1: Management Feels It "Can\'t Be Controlled"'}),"\n",(0,i.jsx)(t.p,{children:'When you propose letting an agent autonomously take over a stretch of development work, a manager\'s first reaction usually isn\'t "how accurate is it?" \u2014 it\'s "how do I control this thing?"'}),"\n",(0,i.jsx)(t.p,{children:"That's not conservatism; it's a reasonable instinct. When traditional code breaks, I have logs, stack traces, and tests to localize the problem. But an agent's reasoning process is a black box \u2014 when it makes a wrong decision, you often can't say which step broke. A system that can't be observed and can't be debugged is, for anyone accountable for outcomes, a system you don't dare put into a production flow."}),"\n",(0,i.jsx)(t.p,{children:"This is precisely one of the core barriers the research identifies. A 2026 interview study of software engineering practitioners (16 interviewees across 12 companies) [1] found these companies stuck at a \"capability-deployment verification gap\": they can build experimental higher-level AI capabilities but can't move them into production because adequate output verification is missing, leaving humans as the only trusted check. Four recurring barriers shape this gap: LLM context-window limits, underperformance on proprietary languages and protocols, non-determinism incompatible with qualification standards, and data-confidentiality concerns. In other words, management's hesitation isn't emotional; it's a normal risk response to a system whose behavior can't be predicted and whose output can't be verified. A separate study spanning engineering and manufacturing (30+ interviews) [10] adds that adoption is constrained less by model capability than by fragmented data, stringent security and regulatory requirements, and legacy toolchains without API access \u2014 governance structures that haven't caught up with agentic capabilities."}),"\n",(0,i.jsx)(t.h2,{id:"wall-2-when-something-breaks-no-one-knows-whos-responsible",children:"Wall #2: When Something Breaks, No One Knows Who's Responsible"}),"\n",(0,i.jsxs)(t.p,{children:["This is the most lethal of the walls \u2014 industry and governance discussions have even given it a fixed name: the ",(0,i.jsx)(t.strong,{children:"accountability gap"}),". IBM uses exactly that framing [13], noting enterprises often lack the ability to monitor agent behavior, review automated decisions, and attribute responsibility when the system causes harm."]}),"\n",(0,i.jsx)(t.p,{children:"An agent can be deployed, monitored, even audited, yet none of that answers the most basic question: when it does something wrong and causes a loss, who's responsible? When responsibility is implicit rather than explicitly assigned to a person, governance fails. Discussions around the NIST AI Risk Management Framework therefore argue [14] that before an agent is allowed to act, a named business and technical owner must be assigned."}),"\n",(0,i.jsx)(t.p,{children:"Industry framing puts it even more bluntly [15]: AI agents lack the legal accountability, moral responsibility, and reputational incentives that ordinary employees inherently carry, so the consequences don't naturally land on anyone \u2014 governance has to actively fill that gap."}),"\n",(0,i.jsxs)(t.p,{children:["Economics, as it happens, gave this dilemma a precise name long ago \u2014 and it's a perfect pun: the ",(0,i.jsx)(t.strong,{children:"principal-agent problem"}),". The theory goes: you (the principal) delegate work to an agent, but you face two built-in obstacles \u2014 you can't fully observe what it actually did (information asymmetry), and its goals may not align with yours. Economics' classic fix is the ",(0,i.jsx)(t.strong,{children:"incentive contract"}),': use bonuses, performance reviews, and reputation to tie the agent\'s interests to yours, so that "acting in its own interest" also means getting your work right.']}),"\n",(0,i.jsxs)(t.p,{children:["Here's the catch. An AI agent is, literally, an agent \u2014 but it knocks out both pillars of that mechanism at once. Its reasoning is a black box, so you ",(0,i.jsx)(t.strong,{children:"can't observe"})," it (that's Wall #1); it has no interests of its own, no performance review, no reputation, so you ",(0,i.jsx)(t.strong,{children:"can't bind it with incentives"}),". So management's inarticulate unease has a textbook name: ",(0,i.jsx)(t.strong,{children:"you've hired an agent you can neither monitor nor contract with."})," This isn't a new problem \u2014 it's a classic one in economics, pushed to its extreme by AI. And \"assigning a named owner\" is, at bottom, tethering an agent that can't be incentivized back onto a person who can \u2014 grounding that broken contract mechanism through a human."]}),"\n",(0,i.jsxs)(t.p,{children:["My own take: people are willing to answer for their own judgment because they can't escape it \u2014 they'll be reviewed, it'll affect their performance rating, it'll have career consequences. An agent has none of that. So when a process shifts from \"this engineer is responsible\" to \"this agent is responsible,\" responsibility isn't transferred \u2014 it ",(0,i.jsx)(t.strong,{children:"evaporates"}),". That's what managers are truly afraid of."]}),"\n",(0,i.jsxs)(t.p,{children:["And it gets worse: even if you want to assign an owner, you find responsibility isn't a ",(0,i.jsx)(t.em,{children:"point"})," \u2014 it's a ",(0,i.jsx)(t.em,{children:"chain"}),'. The person who wrote the agent, the person who reviewed its output, the person who hit merge, the person who configured the automated checks \u2014 every link touched that code. When something breaks, each of them can reasonably say "it wasn\'t only me." Applied ethics has a long-standing name for this \u2014 the "problem of many hands": when an outcome is brought about by many people together, no single individual can be cleanly held to account for it.']}),"\n",(0,i.jsxs)(t.p,{children:["Let me head off a common objection here: why not just have another agent review this agent's output? Indeed, in real-world loop implementations the \"find the error\" step (verification) is increasingly handed to a second agent acting as reviewer. But that doesn't solve the accountability problem \u2014 it demonstrates it more clearly. Because even in those highly automated setups, the one who hits merge is still a human. In other words: ",(0,i.jsx)(t.strong,{children:'an agent can automate "finding the error," but not "answering for the release."'})," Verification is the causal side, and it can be outsourced layer by layer to agents; accountability is the answering-for-it side, and it doesn't disappear \u2014 it just gets pushed onto whoever decides whether to trust that layer of agent review. Stack as many agent reviewers as you like; the accountability anchor doesn't vanish, it moves up one notch, and still comes to rest on a person."]}),"\n",(0,i.jsxs)(t.p,{children:["I think you have to be honest about this: ",(0,i.jsx)(t.strong,{children:'there\'s no clean right answer, and anyone who says "it should just be person X" is oversimplifying.'})," But it can be decomposed. The key is to separate two things that get conflated: ",(0,i.jsx)(t.em,{children:"causal responsibility"})," (whose lapse produced the bug) \u2014 usually multi-causal, established after the fact \u2014 and ",(0,i.jsx)(t.em,{children:"accountability"})," (who answers for it) \u2014 which the system assigns ",(0,i.jsx)(t.em,{children:"in advance"}),", and shouldn't be argued about only after something breaks. Most organizational pain comes from thinking they're looking for the first (whose fault) when what they actually lack is the second (who's accountable) \u2014 and the second never had to equal the person who erred. Like aviation safety: the captain is accountable for the whole aircraft, which doesn't mean they tightened every screw."]}),"\n",(0,i.jsxs)(t.p,{children:["The pragmatic move isn't to elect \"the one person responsible\" \u2014 it's to make ",(0,i.jsx)(t.em,{children:"each link accountable for its own decision"}),": whoever designs the agent and its automated checks owns the ",(0,i.jsx)(t.em,{children:"capability boundary"})," (what the agent is authorized to do, what the checks cover, whether that's reasonable); whoever reviews owns ",(0,i.jsx)(t.em,{children:"that particular judgment"})," (given the information they had, should this change pass); whoever hits merge owns the ",(0,i.jsx)(t.em,{children:"release decision"})," \u2014 the final gate. That's fairer than anointing a single super-owner, and far more auditable. Which is exactly why \"merge authority exclusive to humans + immutable audit logs\" matters so much: rather than argue about fault after the fact, make every decision leave a named trail beforehand. When something breaks, you don't argue \u2014 you read the log and trace each layer back."]}),"\n",(0,i.jsxs)(t.p,{children:["Worth adding: a plane has a captain, but an agent pipeline has none by default \u2014 it's missing exactly that role that's accountable for the release as a whole. So merge authority isn't something that pre-exists and we assign; it's a captain we ",(0,i.jsx)(t.strong,{children:"deliberately manufacture"}),". That's also why \"let the agent auto-merge\" is so dangerous in accountability terms: it's a plane with no captain. Incidentally, the hardest link to trace is \"the check nobody set up\" \u2014 an absence doesn't throw an error, so you may never notice it's missing; the fix is the same layering: make required checks org-level enforced with any bypass leaving a named trail, turning \"there's no check here\" from an ownerless vacuum into a decision with someone's name on it."]}),"\n",(0,i.jsx)(t.h2,{id:"wall-3-colleagues-fear-being-replaced",children:"Wall #3: Colleagues Fear Being Replaced"}),"\n",(0,i.jsx)(t.p,{children:"After the technical conversation and the governance conversation, this last wall is the quietest \u2014 and the hardest to take down."}),"\n",(0,i.jsx)(t.p,{children:'When you ask a team to "use AI to take on part of the work," you think you\'re talking about efficiency. But what a frontline engineer may hear is a signal that the organization is preparing to replace this role. That feeling turns into silent resistance \u2014 nominal compliance, but in practice they route around it, treat it as a showpiece, and adoption never climbs.'}),"\n",(0,i.jsx)(t.p,{children:'There\'s a large body of empirical work on this in organizational behavior. The most-cited framework, STARA awareness [2], found that the more aware employees are of "smart technology, artificial intelligence, robotics, and algorithms," the lower their organizational commitment and career satisfaction, and the higher their turnover intentions. And a multilevel systematic review (Bankins et al., 2024) [3] notes that employees who fear AI worry not just about their jobs but about damage to their skills and careers, which drives down engagement and commitment and raises resistance and turnover \u2014 the threat is often less about unemployment than about a professional identity under threat. AI disrupts not just tasks, but the psychological contract that gives the work meaning.'}),"\n",(0,i.jsx)(t.p,{children:'And there\'s an ironic mechanism playing out daily here: when you "ask" a senior engineer to train or calibrate the very agent meant to take over their work, you\'re asking them to hand-accelerate their own marginalization. They know it, so the resistance shows up in the hardest-to-detect form \u2014 not refusal, but "compliance without investment": training data one layer too shallow, agent errors quietly not reported, the most critical tacit knowledge kept in their head and never written into a skill. What you see is adoption stalling; what\'s actually happening is that the very expert judgment most worth digitizing is being silently withheld.'}),"\n",(0,i.jsxs)(t.p,{children:["For a profession with as strong an identity as engineering, this gets amplified. What you're touching isn't their working hours \u2014 it's the thing that makes them who they are. That's why Wall #3 can't be forced down with \"communication\" or a raise \u2014 it requires letting the engineer ",(0,i.jsx)(t.em,{children:"win a new position"}),' in the transition, not just be soothed. Which connects straight to the solutions later: turning them from "the person the agent replaces" into "the person who defines the agent\'s boundaries."']}),"\n",(0,i.jsx)(t.p,{children:"But here's something managers easily misjudge: employees aren't a monolith of \"collective resistance.\" Teams have always split into factions \u2014 this isn't new. Rogers' diffusion of innovations theory sorted adopters back in 1962 into innovators, early adopters, early majority, late majority, and laggards [18]. A recent empirical study of developers using AI tools goes further [19], clustering engineers into three groups \u2014 Enthusiasts, Pragmatists, and Cautious \u2014 that differ markedly in usage breadth, perceived productivity and quality, and future adoption intent. In other words, your team already contains both reformers and conservatives, and the agent won't flatten that fault line \u2014 it will surface it, and may deepen it."}),"\n",(0,i.jsxs)(t.p,{children:['For leadership, that\'s a lever, not a headache. The real mistake is spending all your energy "soothing the conservatives"; the more effective move is to ',(0,i.jsx)(t.strong,{children:"identify and empower the reformers first"})," \u2014 they're often the team's opinion leaders, and peer-to-peer, lateral diffusion from them is far more persuasive than top-down mandates from a manager. Pragmatists will follow once they see proof of success and organizational support; the cautious need more time and reassurance. Your job isn't to get everyone on board the same day \u2014 it's to let the reformers run first and blaze the trail for the rest to see."]}),"\n",(0,i.jsx)(t.h2,{id:"wall-4-when-the-agent-dismantles-your-role-whos-approving-that-pr",children:"Wall #4: When the Agent Dismantles Your Role, Who's Approving That PR?"}),"\n",(0,i.jsxs)(t.p,{children:["The first three walls are about \"whether to adopt.\" But once it's actually live, there's a finer and less-discussed wall: an agent doesn't cleanly replace a person \u2014 it ",(0,i.jsx)(t.strong,{children:"takes a role apart and reassembles it"})," \u2014 and that reassembly quietly moves responsibility to a spot no one was ready for."]}),"\n",(0,i.jsxs)(t.p,{children:["Research describes this more precisely than I'd expected. One line of work [4] argues that reducing AI's impact to \"replace vs. augment\" isn't enough; what actually happens is task ",(0,i.jsx)(t.em,{children:"chaining"}),': on one hand, AI pulls previously manual steps "under the hood" of a single task, narrowing the span of activity a human directly handles and shifting responsibility ',(0,i.jsx)(t.em,{children:"within"})," a role; on the other, it lowers the cost of chaining steps across a job boundary, making it rational to redraw that boundary and reassign activities ",(0,i.jsx)(t.em,{children:"between"})," roles. A separate line [5] decomposes a role into execution, search, coordination, judgment, and accountability, arguing agents take the front end (execution, search, drafting) while humans should retain context, judgment, and accountability. Both point to the same thing: an engineer's job gets split, the agent takes the first few pieces, but \"accountability\" doesn't disappear with them \u2014 it just gets pushed downstream."]}),"\n",(0,i.jsxs)(t.p,{children:["And where does it get pushed to? ",(0,i.jsx)(t.strong,{children:"Code review."})]}),"\n",(0,i.jsxs)(t.p,{children:["This is my deepest takeaway from the past year, and the research happens to back it up. When an agent generates code at volume, the bottleneck shifts from ",(0,i.jsx)(t.em,{children:"writing"})," code to ",(0,i.jsx)(t.em,{children:"reviewing"})," AI-generated code \u2014 and every AI suggestion has to be read with suspicion until proven correct. Studies call this the ",(0,i.jsx)(t.em,{children:"oversight burden"})," [8] and note it's the most underestimated hidden cost of adopting AI in software engineering, sometimes consuming more effort than it saves."]}),"\n",(0,i.jsxs)(t.p,{children:["More critically, where responsibility lands. A survey study on the future of code review (100 developers across 5 companies) [6] found developers broadly expect code review ",(0,i.jsx)(t.em,{children:"not"})," to disappear \u2014 they anticipate similar or greater effort and a broader range of artifacts under review, and nearly all expect LLMs to become active participants in the process. Building on that trajectory, a paper proposing an agentic code review architecture (Kamal\u0131 et al., 2026) [7] envisions a future in which reviewers shift from manual inspectors into supervisory operators of agents. Put the two together and the direction is clear: review doesn't get replaced by the agent \u2014 it gets pushed up a level, where a human no longer reads every line but supervises the agents that do."]}),"\n",(0,i.jsxs)(t.p,{children:["To put it plainly for leadership: ",(0,i.jsx)(t.strong,{children:"when a module the agent wrote breaks, responsibility doesn't stop at the agent \u2014 it slides all the way down and stops at the reviewer who hit approve."})," That means two things. First, code review is upgraded from a hygiene habit into the accountability anchor of the entire pipeline \u2014 it's ",(0,i.jsx)(t.em,{children:"more"})," important after agents ship, not less. Second, if a company hasn't thought this through, it's effectively letting one engineer silently bear the full consequences of an AI output they may not even be equipped to fully review. That's unfair to the reviewer, and an undefended risk to the company."]}),"\n",(0,i.jsxs)(t.p,{children:["This isn't just theory. Stripe has published a representative case [17]: its internal autonomous coding agent (codenamed Minions) produces over 1,300 PRs a week containing zero human-written code \u2014 yet ",(0,i.jsx)(t.strong,{children:"every one is still reviewed by a human before it merges."})," People haven't left the process; their seat changed, from writing code to reviewing it. More telling still, a counterintuitive point runs through the case: what makes it scale has almost nothing to do with model power, and everything to do with the developer infrastructure Stripe built years earlier for humans \u2014 sandboxed devboxes, comprehensive test suites, CI and deterministic gates. In their engineers' words, if your dev environment, test infrastructure, and feedback loops are solid, agents benefit from them; if they're not, no model will save you. The lesson matters especially for leadership \u2014 ",(0,i.jsx)(t.strong,{children:"for loop-based work, one solid verification gate matters more than raw model power."})," In other words, what decides whether this scales isn't how smart the AI is, but how well you've designed your accountability gates."]}),"\n",(0,i.jsxs)(t.p,{children:["There's another economic mechanism hiding here that managers must grasp: ",(0,i.jsx)(t.strong,{children:"moral hazard"}),'. It describes what happens when someone doesn\'t bear the consequences of their own actions \u2014 they quietly take on too much risk, or slack off on diligence. Auto-merging agent output, or letting review become a rubber stamp, is a textbook breeding ground for it: when the person hitting approve knows "responsibility is diffuse anyway, and it won\'t trace back to me," the honesty of their review erodes systematically \u2014 not because they\'re bad, but because the incentive structure permits them to coast. This is the real organizational consequence of "evaporating responsibility": ',(0,i.jsx)(t.strong,{children:"once accountability is diluted, oversight quality declines with it."}),' Conversely, this is exactly why "named ownership + an immutable audit trail" isn\'t bureaucratic red tape but a ',(0,i.jsx)(t.strong,{children:"repair to incentives"})," \u2014 it ties consequences back onto the person making the decision, giving them a reason to review in earnest."]}),"\n",(0,i.jsxs)(t.p,{children:["And moral hazard has a more upstream version that managers often manufacture with their own hands: ",(0,i.jsx)(t.strong,{children:'turning "use AI to go faster" directly into a performance KPI.'}),' The intent is usually good \u2014 a manager wants to drive adoption, so they reward visible numbers like "AI suggestion acceptance rate," PR count, or delivery speed. But that walks straight into Goodhart\'s law: when a measure becomes a target, it stops being a good measure. As one commentary puts it bluntly [16], if "AI suggestion acceptance rate" becomes a KPI, you\'re rewarding engineers for blindly accepting low-quality AI code \u2014 in effect, ',(0,i.jsx)(t.strong,{children:"measuring their willingness to switch off critical thinking."})," A speed metric systematically manufactures speed-driven lapses."]}),"\n",(0,i.jsx)(t.p,{children:'And this top-down incentive distortion has a harder-to-admit extreme: sometimes a manager\'s real motive for pushing agents isn\'t efficiency \u2014 it\'s to route around people. A manager who has lost faith in their team, or has had enough of certain hard-to-manage senior engineers, may treat the agent as the solution that "finally lets me not depend on these people" \u2014 rather than repair a team they believe can\'t be fixed, bring in an outside force to reorganize an order they can no longer control. This is more dangerous than foot-dragging from below, because it comes from the end that holds decision-making power, and it quietly turns the agent from "a tool that helps the team" into "a pretext to replace it." So before designing any KPI or rollout plan, leadership owes itself an honest question: am I pushing this agent to make the team stronger, or to avoid having to face this team at all?'}),"\n",(0,i.jsxs)(t.p,{children:['And there\'s no free lunch here. Research points out [9] that "review everything" causes velocity collapse \u2014 review overhead eats the entire productivity gain the agent brought \u2014 while "review nothing" produces unauditable, non-compliant code. So the answer isn\'t either/or; it\'s ',(0,i.jsx)(t.strong,{children:"risk-graduated human oversight"})," \u2014 high-risk changes bound tightly to human review and named responsibility, low-risk ones let through. Which loops right back to the first three walls: observable, named ownership, humans kept in the loop."]}),"\n",(0,i.jsx)(t.h2,{id:"an-old-fault-line-amplified-by-agents-security-vs-rd",children:"An Old Fault Line, Amplified by Agents: Security vs. RD"}),"\n",(0,i.jsxs)(t.p,{children:['One subplot worth flagging. The layered accountability, capability boundaries, and enforced gates from Wall #2 all land on a long-standing fault line inside companies: security wants gates and control, RD wants speed and autonomy. This tension is empirically documented \u2014 a systematic review of DevSecOps [11] found the biggest "people" problem is exactly the conflict between development and security teams, with developers feeling judged and stripped of autonomy; another study [12] locates the root in ',(0,i.jsx)(t.em,{children:"differing objective functions"}),' \u2014 RD wants to ship fast, security wants a thorough assessment, and both are doing the "right" thing by different definitions. So it\'s structural, not a communication problem.']}),"\n",(0,i.jsx)(t.p,{children:'And agents move where that fault line sits. Security used to gate "code RD was confident in," so RD felt nitpicked; now both sides face "AI output not even RD is sure of." It\'s the first time RD and security share an enemy \u2014 and that gate flips from "policing RD" to "protecting RD," shielding the engineer who\'d otherwise carry the AI\'s consequences alone. That\'s why my solutions below hold up: on the surface they\'re security\'s demands; underneath, they\'re spreading responsibility off of RD. Whoever can make the team see that shift turns the deepest resistance into a driving force.'}),"\n",(0,i.jsx)(t.h2,{id:"so-what-do-you-do--four-handholds-not-answers",children:"So What Do You Do? \u2014 Four Handholds, Not Answers"}),"\n",(0,i.jsx)(t.p,{children:"I won't pretend to have a complete solution, but after this year, here are the directions I think are worth pursuing:"}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"First, make the agent observable before you talk about autonomy."})," The concrete bar: every action the agent takes \u2014 which tool it called, which file it changed, on what basis it decided \u2014 must map to a traceable log line, the kind you'd read when debugging a normal bug. Be honest here: traceable isn't the same as understandable \u2014 a log line tells you what the agent did, not why it decided that way, and the reasoning black box won't vanish soon. But that's exactly the point: if you can't fully see its \"thinking,\" you must at least be able to fully reconstruct its \"behavior.\" Until you can do that, don't talk about autonomy. A human review checkpoint at this stage isn't the enemy of autonomy \u2014 it's the entry ticket that gives the agent a chance to be accepted. Make it reconstructable first, then loosen the reins."]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:'Second, treat "layered, named accountability" as a precondition for deployment, not an afterthought.'})," Stop asking \"who's the one person responsible\" \u2014 there isn't one. Make every decision in the chain named and logged: who authorized the agent, who approved, who merged, which checks passed at the time. The accountability gap isn't something technology can patch \u2014 it's something the system has to design for by distributing responsibility across layers up front. When something breaks, you should be able to read the log and trace it back, not argue about it in a meeting room."]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Third, have engineers write the agent's capability boundary list by hand."}),' "Involve employees" sounds like a slogan; the concrete handhold is an actual artifact: let the engineer who owned that area define this agent\'s allowlist / denylist \u2014 which files it can touch, which APIs it can call, which operations always require human review. This isn\'t a format I invented; in real loop implementations, people already encode it as a fixed "Stop" section in the agent\'s config file, spelling out in black and white "never merge, never delete, never push to main, send anything uncertain to a human" \u2014 and their experience is blunt: the red line you don\'t write down is one the agent will eventually cross for you. It loops right back to the layered accountability from Wall #2: the engineer who owned that area is already the person best placed to define that "capability boundary" layer. Their role is upgraded from "the person who writes the code" to "the person who defines how the agent should write code" \u2014 that\'s not consolation, it\'s a real step up in scope. Resistance loosens not because they were invited to a meeting to speak, but because they actually hold a set of rules that can say stop.']}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Fourth, treat code review as the accountability anchor, and graduate it with an explicit line."}),' Admit one thing: when an agent dismantles a role, the person hitting approve is where responsibility lands. Rather than let that happen silently, say it out loud \u2014 and make "risk" concrete: changes that touch production data, alter permissions or security logic, or modify external interfaces always get a named human reviewer; only purely internal tooling, tests, and docs auto-merge. Where exactly to draw the line is debatable, but there has to be an explicit line, not a gut feeling. And keep an auditable decision trail throughout. This doesn\'t slow AI down; it keeps speed from bypassing responsibility.']}),"\n",(0,i.jsx)(t.h2,{id:"back-to-first-principles-none-of-these-walls-were-built-by-the-agent",children:"Back to First Principles: None of These Walls Were Built by the Agent"}),"\n",(0,i.jsx)(t.p,{children:'Having gotten this far, I want to step back and make one thing clear, so this piece doesn\'t get read as "and therefore the agent is a troublemaker."'}),"\n",(0,i.jsxs)(t.p,{children:["Look back at these five obstacles \u2014 management can't control it, no one's accountable when it breaks, employees fear replacement, roles get taken apart and reassembled, security versus RD \u2014 and ",(0,i.jsx)(t.strong,{children:"not one of them was invented by the agent."})]}),"\n",(0,i.jsx)(t.p,{children:'Management was never good at governing what it can\'t see through; it\'s just that the black box used to be "the tacit know-how inside some senior engineer\'s head," and now it\'s a model\'s reasoning. Responsibility attribution was always a tangle of "many hands"; it just limped along on implicit understandings ("this module is yours") and nobody forced you to make it explicit. Fear of replacement has shown up in every technological wave, from the Industrial Revolution to ERP rollouts to offshoring. The boundaries of roles and R&R were always going to be redrawn as tools change. And the goal conflict between security and RD existed for decades before the word "DevSecOps" was coined.'}),"\n",(0,i.jsxs)(t.p,{children:["In other words, ",(0,i.jsx)(t.strong,{children:"the agent isn't the cause of these ailments \u2014 it's the contrast dye."})," What it actually does is illuminate, all at once and mercilessly, the cracks a company normally papers over with interpersonal trust, seniority, and gray areas. Introduce an agent into a well-governed organization and it reveals a few hairline cracks; introduce it into one that was already running on tacit understanding, and it reveals an entire wall of fractures."]}),"\n",(0,i.jsxs)(t.p,{children:["For leadership, that's good news, not bad. Because it means: ",(0,i.jsx)(t.strong,{children:"every single thing you're forced to do to make the agent operate safely \u2014 spelling out layered accountability, writing the red lines into a list, making checks mandatory, pulling security and RD to the same table \u2014 none of it is useful for the agent alone."})," These are the fundamentals your organization should have had all along but never had the impetus to build. The agent just finally gave you a reason you can't refuse."]}),"\n",(0,i.jsxs)(t.p,{children:['So the real question was never "should we adopt agents." It\'s the harder, worthier one: ',(0,i.jsx)(t.strong,{children:"are we willing to use this occasion to close, one by one, the holes that tacit understanding has been hiding."})]}),"\n",(0,i.jsx)(t.p,{children:"Agentic AI often fails to get off the ground not because it isn't capable enough, but because it exposes the holes that already existed in a company's governance, accountability, people, and division of labor. The technology will keep improving \u2014 but these walls were never built by the agent, and only the organization can take them down."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"references",children:"References"}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"Academic papers (peer-reviewed / preprints)"})}),"\n",(0,i.jsxs)(t.ol,{children:["\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:["Apostolou, S. A., Bosch, J., & Holmstr\xf6m Olsson, H. (2026). ",(0,i.jsx)(t.em,{children:"Agentic AI in Industry: Adoption Level and Deployment Barriers."})," arXiv:2605.14675. ",(0,i.jsx)(t.a,{href:"https://arxiv.org/abs/2605.14675",children:"https://arxiv.org/abs/2605.14675"}),'\n\u2014 Interview study across 16 practitioners at 12 companies; introduces a "capability\u2013deployment verification gap." The four barriers are: LLM context-window limits, underperformance on proprietary languages/protocols, non-determinism, and data confidentiality. (Wall #1)']}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:["Brougham, D., & Haar, J. (2018). ",(0,i.jsx)(t.em,{children:"Smart Technology, Artificial Intelligence, Robotics, and Algorithms (STARA): Employees' perceptions of our future workplace."})," Journal of Management & Organization, 24(2), 239\u2013257. ",(0,i.jsx)(t.a,{href:"https://doi.org/10.1017/jmo.2016.55",children:"https://doi.org/10.1017/jmo.2016.55"}),"\n\u2014 The original STARA awareness paper. Greater awareness correlates with lower organizational commitment and career satisfaction, and higher turnover intentions, cynicism, and depression. (Wall #3)"]}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:["Bankins, S., Ocampo, A. C., Marrone, M., Restubog, S. L. D., & Woo, S. E. (2024). ",(0,i.jsx)(t.em,{children:"A multilevel review of artificial intelligence in organizations: Implications for organizational behavior research and practice."})," Journal of Organizational Behavior. ",(0,i.jsx)(t.a,{href:"https://doi.org/10.1002/job.2735",children:"https://doi.org/10.1002/job.2735"}),"\n\u2014 Multilevel systematic review; employees who fear AI worry about replacement and damage to skills/careers, driving down engagement and commitment and raising resistance and turnover. (Wall #3)"]}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.em,{children:"Chaining Tasks, Redefining Work: A Theory of AI Automation."})," (2026). arXiv:2606.15960. ",(0,i.jsx)(t.a,{href:"https://arxiv.org/abs/2606.15960",children:"https://arxiv.org/abs/2606.15960"}),'\n\u2014 Argues the "replace vs. augment" dichotomy is insufficient; AI shifts responsibility within roles and redraws job boundaries through task chaining. (Wall #4: role reconfiguration)']}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.em,{children:"The Integrator Advantage: Controlled Agentic AI for Small and Medium-Sized Companies."})," (2026). arXiv:2606.16649. ",(0,i.jsx)(t.a,{href:"https://arxiv.org/abs/2606.16649",children:"https://arxiv.org/abs/2606.16649"}),'\n\u2014 Decomposes a role into execution, search, coordination, judgment, accountability, etc.; argues agents take the front end while humans retain context and responsibility. The right question is "which human time can be multiplied," not "who can be replaced." (Wall #4)']}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:["Dorner, M., Bauer, A., \u0160mite, D., Thode, L., Mendez, D., Britto, R., Lukasczyk, S., Zabardast, E., & Kormann, M. (2025). ",(0,i.jsx)(t.em,{children:"Quo Vadis, Code Review? Exploring the Future of Code Review."})," arXiv:2508.06879. ",(0,i.jsx)(t.a,{href:"https://arxiv.org/abs/2508.06879",children:"https://arxiv.org/abs/2508.06879"}),"\n\u2014 Survey of 100 developers across 5 companies. Developers expect code review ",(0,i.jsx)(t.em,{children:"not"})," to disappear \u2014 anticipating similar or greater effort and a broader range of reviewed artifacts, with nearly all expecting LLMs to become active participants. (Wall #4)"]}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:["Kamal\u0131, H. \xd6., Tuna, E., Haratian, V., & T\xfcz\xfcn, E. (2026). ",(0,i.jsx)(t.em,{children:"Rethinking Code Review in the Age of AI: A Vision for Agentic Code Review."})," arXiv:2605.17548. ",(0,i.jsx)(t.a,{href:"https://arxiv.org/abs/2605.17548",children:"https://arxiv.org/abs/2605.17548"}),"\n\u2014 A vision paper arguing reviewers shift from manual inspectors into supervisory operators of agents, with a framework carrying context across review stages. (Wall #4)"]}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:["Garousi, V. (2026). ",(0,i.jsx)(t.em,{children:"Human Oversight and Overload: Two Hidden and Costly Burdens of AI-Assisted Software Engineering."})," arXiv:2606.05770. ",(0,i.jsx)(t.a,{href:"https://arxiv.org/abs/2606.05770",children:"https://arxiv.org/abs/2606.05770"}),"\n\u2014 Characterizes two underestimated burdens: the constant need for human oversight of AI-generated artifacts, and cognitive overload from the flood of AI suggestions. (Wall #4)"]}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.em,{children:"Governed AI-Assisted Engineering: Graduated Human Oversight for Agentic Code Generation in Regulated Domains."})," (2026). arXiv:2606.22484. ",(0,i.jsx)(t.a,{href:"https://arxiv.org/abs/2606.22484",children:"https://arxiv.org/abs/2606.22484"}),"\n\u2014 Presents the GAIE framework and Oversight Classification Model (OCM), routing tasks by regulatory impact, customer proximity, reversibility, and data sensitivity into three oversight tiers (human-in-the-loop / human-over-the-loop / automated-with-monitoring). (Wall #4 and the closing directions)"]}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.em,{children:"Agentic AI in Engineering and Manufacturing: Industry Perspectives on Utility, Adoption, Challenges, and Opportunities."})," (2026). arXiv:2604.09633. ",(0,i.jsx)(t.a,{href:"https://arxiv.org/abs/2604.09633",children:"https://arxiv.org/abs/2604.09633"}),"\n\u2014 Exploratory study grounded in 30+ interviews; finds adoption is constrained less by model capability than by fragmented data, security/regulatory requirements, and legacy toolchains lacking API access. (Wall #1)"]}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:["Rajapakse, R. N., Zahedi, M., Babar, M. A., & Shen, H. (2021). ",(0,i.jsx)(t.em,{children:"Challenges and Solutions When Adopting DevSecOps: A Systematic Review."})," arXiv:2103.08266. ",(0,i.jsx)(t.a,{href:"https://arxiv.org/abs/2103.08266",children:"https://arxiv.org/abs/2103.08266"}),'\n\u2014 Systematic review finding that the largest "people" challenge is conflict between development and security teams: developers feel judged and stripped of autonomy. (Security vs. RD fault line)']}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.em,{children:"Collaborative Application Security Testing for DevSecOps: An Empirical Analysis of Challenges, Best Practices and Tool Support."})," (2022). arXiv:2211.06953. ",(0,i.jsx)(t.a,{href:"https://arxiv.org/abs/2211.06953",children:"https://arxiv.org/abs/2211.06953"}),"\n\u2014 Empirical analysis documenting how development and security teams take an adversarial stance because their objective functions differ (delivery speed vs. thorough security assessment). (Security vs. RD fault line)"]}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"Industry reports & governance frameworks (not peer-reviewed; for further reading)"})}),"\n",(0,i.jsxs)(t.ol,{start:"13",children:["\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:["IBM (2026). ",(0,i.jsx)(t.em,{children:"The accountability gap in autonomous AI."})," ",(0,i.jsx)(t.a,{href:"https://www.ibm.com/think/insights/accountability-gap-autonomous-ai",children:"https://www.ibm.com/think/insights/accountability-gap-autonomous-ai"}),"\n\u2014 Notes enterprises often lack the ability to monitor agent behavior, review automated decisions, and attribute responsibility after the fact. (Wall #2)"]}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:["SPHERE / NHIMG (2026). ",(0,i.jsx)(t.em,{children:"AI Agent Ownership \u2014 An Underlying NIST AI RMF Control."})," ",(0,i.jsx)(t.a,{href:"https://nhimg.org/community/agentic-ai-and-nhis/ai-agent-ownership-and-accountability-gaps-in-ai-governance/",children:"https://nhimg.org/community/agentic-ai-and-nhis/ai-agent-ownership-and-accountability-gaps-in-ai-governance/"}),"\n\u2014 Argues a named business and technical owner should be assigned before an agent is allowed to act, treating ownership as a prerequisite control for governance. (Wall #2)"]}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:["World Economic Forum (2026). ",(0,i.jsx)(t.em,{children:"Why autonomous AI demands a new model of organizational authority."})," ",(0,i.jsx)(t.a,{href:"https://www.weforum.org/stories/2026/05/autonomous-ai-new-model-organizational-authority/",children:"https://www.weforum.org/stories/2026/05/autonomous-ai-new-model-organizational-authority/"}),"\n\u2014 Notes AI agents lack the legal accountability, moral responsibility, and reputational incentives of regular employees; consequences aren't intrinsic, so governance must compensate for the gaps. (Wall #2)"]}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:["Hamade, J. (2025). ",(0,i.jsx)(t.em,{children:"Beyond the Hype: A Leader's Guide to Software Development Metrics in the Age of AI."})," Medium. ",(0,i.jsx)(t.a,{href:"https://medium.com/@justhamade/beyond-the-hype-a-leaders-guide-to-software-development-metrics-in-the-age-of-ai-129cd6d2fa7b",children:"https://medium.com/@justhamade/beyond-the-hype-a-leaders-guide-to-software-development-metrics-in-the-age-of-ai-129cd6d2fa7b"}),'\n\u2014 Industry commentary. Argues that making "AI suggestion acceptance rate" a KPI incentivizes blindly accepting low-quality AI code \u2014 measuring willingness to switch off critical thinking; any speed metric must be counter-balanced by a quality metric. (Wall #4: KPI incentives)']}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:["Stripe Engineering (2026), via InfoQ. ",(0,i.jsx)(t.em,{children:"Stripe Engineers Deploy Minions, Autonomous Agents Producing Thousands of Pull Requests Weekly."})," ",(0,i.jsx)(t.a,{href:"https://www.infoq.com/news/2026/03/stripe-autonomous-coding-agents/",children:"https://www.infoq.com/news/2026/03/stripe-autonomous-coding-agents/"}),'\n\u2014 Stripe\'s autonomous coding agents ("Minions") produce 1,300+ PRs/week with zero human-written code, yet all changes are human-reviewed before merge; scaling hinges on existing developer infrastructure (sandboxed devboxes, tests, CI and deterministic gates), not model power. (Wall #4: humans relocated to reviewers)']}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"Organizational behavior & technology adoption (academic)"})}),"\n",(0,i.jsxs)(t.ol,{start:"18",children:["\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:["Rogers, E. M. (1962/2003). ",(0,i.jsx)(t.em,{children:"Diffusion of Innovations."})," Free Press.\n\u2014 Classic theory sorting adopters into innovators, early adopters, early majority, late majority, and laggards; early adopters hold the highest opinion leadership and are key to peer diffusion. (Wall #3: employee factions)"]}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.em,{children:"AI Tools in Software Development: Developer Perceptions and Usage Patterns."})," (2026). arXiv:2601.21305. ",(0,i.jsx)(t.a,{href:"https://arxiv.org/abs/2601.21305",children:"https://arxiv.org/abs/2601.21305"}),"\n\u2014 Empirical clustering study sorting developers into Enthusiasts, Pragmatists, and Cautious groups that differ in usage breadth, perceived productivity/quality, and future adoption intent, mapping onto Rogers' adopter categories. (Wall #3: employee factions)"]}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"Verification & citation status:"})}),"\n",(0,i.jsxs)(t.ol,{children:["\n",(0,i.jsx)(t.li,{children:"Independently verified (arXiv ID/DOI, title, authors, year all match): items 1, 2, 3, 6, 7, 8, 9, 10, 11, 19; items 13, 14, 15, 16, 17 (IBM, SPHERE, World Economic Forum, Hamade, Stripe/InfoQ) all exist and are confirmed; item 18 (Rogers, Diffusion of Innovations) is a classic text. Stripe Minions' \"1,300+ PRs/week, all human-reviewed\" is corroborated by Stripe's engineering blog and multiple primary write-ups (including InfoQ quoting a Stripe engineering manager's public post)."}),"\n",(0,i.jsxs)(t.li,{children:["Items 4 (",(0,i.jsx)(t.em,{children:"Chaining Tasks, Redefining Work"}),") and 5 (",(0,i.jsx)(t.em,{children:"The Integrator Advantage"}),") have ",(0,i.jsx)(t.strong,{children:"not"}),' been independently re-verified for their exact arXiv IDs; Wall #4 therefore attributes them softly ("one line of work argues"). Check arXiv for the correct ID/authors before citing, or substitute a confirmed source.']}),"\n",(0,i.jsxs)(t.li,{children:['The "problem of many hands" is an established concept in applied ethics (traceable to D. Thompson and others); this piece uses it as a standalone concept and does ',(0,i.jsx)(t.strong,{children:"not"})," claim any of the code-review papers above originated it."]}),"\n",(0,i.jsx)(t.li,{children:'"Principal-agent problem," "moral hazard," "sin of omission," "Coasean transaction costs," and "Goodhart\'s law" are textbook economics/management concepts not tied to a specific paper here; for formal attribution, add primary sources such as Jensen & Meckling (1976), Holmstr\xf6m (1979), and Goodhart (1975)/Strathern (1997).'}),"\n",(0,i.jsx)(t.li,{children:'The "Stop section in an agent config" description (in solution 3) comes from a secondary industry piece on Loop Engineering whose details couldn\'t be fully independently verified, so the text says "in real loop implementations"; find a primary source before formal use.'}),"\n",(0,i.jsx)(t.li,{children:'Items 13\u201314 are industry/governance pieces; items 15, 16, 17 are industry reports, an engineering blog, or individual commentary rather than academic papers. The governance arguments ("named owner," "human-in-the-loop checkpoint," "speed metrics need a quality counter-metric") are echoed across BCG, MIT Sloan Management Review, OECD, and the EU AI Act (Articles 12\u201314).'}),"\n"]}),"\n"]})]})}function d(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var a=n(96540);let i={},o=a.createContext(i);function s(e){let t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(o.Provider,{value:t},e.children)}}}]);